/*
 * Speakers for four agenda sessions that had none (ADR 0095).
 *
 * "Networking and Visibility", "Is Your 'Sign in with...' Button Really Safe?",
 * "Au-dela de la technologie..." and "GenUI..." are on the agenda but were
 * added to the site title-only (0036). Their speakers are in the Sessionize
 * export (listed there as Declined, though the agenda schedules them): this
 * adds the four speakers as VISIBLE profiles and fills each session's real
 * abstract, level, language and tags.
 *
 * SAFE: a speaker is appended only if its id is missing; a session is
 * updated only while it still has NO speaker, so anything an organiser has
 * filled in from the dashboard since is left alone. Idempotent. Both rows are
 * snapshotted first.
 */
insert into public.editorial_migration_backup (migration, document_id, payload)
select '0043', d.id, d.payload
from public.editorial_documents d
where d.id in ('speakers', 'sessions')
on conflict (migration, document_id) do nothing;

update public.editorial_documents d
set payload = d.payload || coalesce((
  select jsonb_agg(x order by o)
  from jsonb_array_elements($sp$[{"id": "forlan-noumechi", "name": "Forlan Noumechi", "role": {"fr": "CEO of Kroma", "en": "CEO of Kroma"}, "company": "", "photoUrl": "/speakers/forlan-noumechi.webp", "bio": {"fr": "Je suis designer et entrepreneur, et fondateur de Kroma, une startup spécialisée dans l’identité visuelle et le design web. Je m’intéresse à l’intersection entre design, technologie et entrepreneuriat, avec une conviction : la valeur d’un produit doit être aussi bien construite que perçue.", "en": "Je suis designer et entrepreneur, et fondateur de Kroma, une startup spécialisée dans l’identité visuelle et le design web. Je m’intéresse à l’intersection entre design, technologie et entrepreneuriat, avec une conviction : la valeur d’un produit doit être aussi bien construite que perçue."}, "track": {"fr": "UX/UI Design", "en": "UX/UI Design"}, "day": 1, "sessionIds": ["agenda-au-dela-de-la-technologie-construire-des-startup"], "social": {"linkedin": "https://www.linkedin.com/in/forlan-djoumegni-481145385", "website": "https://kroma-agence.com"}, "icebreakerQuestion": {"fr": "", "en": ""}, "icebreakerAnswer": {"fr": "", "en": ""}}, {"id": "yunwen-eric", "name": "Yunwen Eric", "role": {"fr": "Building the Future with Flutter | Web Developer | Community Lead | STEM Advocate", "en": "Building the Future with Flutter | Web Developer | Community Lead | STEM Advocate"}, "company": "", "photoUrl": "/speakers/yunwen-eric.webp", "bio": {"fr": "Software developer with a keen interest in both Flutter and web development. Originating from Africa, I'm deeply passionate about leveraging technology to make a difference, particularly in Africa's development. Beyond coding, I actively engage in community initiatives, striving to foster growth and collaboration within the tech ecosystem. I'm particularly passionate about promoting STEM education in Africa. Whether it's through building software, community engagements, or advocating for STEM education, I'm dedicated to making a positive impact in the world.", "en": "Software developer with a keen interest in both Flutter and web development. Originating from Africa, I'm deeply passionate about leveraging technology to make a difference, particularly in Africa's development. Beyond coding, I actively engage in community initiatives, striving to foster growth and collaboration within the tech ecosystem. I'm particularly passionate about promoting STEM education in Africa. Whether it's through building software, community engagements, or advocating for STEM education, I'm dedicated to making a positive impact in the world."}, "track": {"fr": "Mobile", "en": "Mobile"}, "day": 1, "sessionIds": ["agenda-genui-making-mobile-interfaces-dynamic-with-ai"], "social": {"linkedin": "https://www.linkedin.com/in/yunweneric", "x": "https://x.com/yunweneric", "website": "https://neero.io/"}, "icebreakerQuestion": {"fr": "", "en": ""}, "icebreakerAnswer": {"fr": "", "en": ""}}, {"id": "steeve-zali", "name": "Steeve Zali", "role": {"fr": "TEKMEN REVOLUTION,C.E.O", "en": "TEKMEN REVOLUTION,C.E.O"}, "company": "", "photoUrl": "/speakers/steeve-zali.webp", "bio": {"fr": "Steeve Zali is a Cameroonian tech entrepreneur, Computer Science student at the University of Buea, and aspiring Data Scientist passionate about innovation and technology-driven solutions. He is the CEO of Tekmen Revolution, a technology company and community dedicated to empowering tech enthusiasts, fostering collaboration, and promoting digital skills and innovation. He also serves as Project Manager and Frontend Engineer for RAYDAR, a child-safety initiative leveraging technology to help protect children. With over 4,000 followers on LinkedIn, Steeve shares his tech journey, connects with emerging innovators, and inspires young people to use technology to create meaningful social impact.", "en": "Steeve Zali is a Cameroonian tech entrepreneur, Computer Science student at the University of Buea, and aspiring Data Scientist passionate about innovation and technology-driven solutions. He is the CEO of Tekmen Revolution, a technology company and community dedicated to empowering tech enthusiasts, fostering collaboration, and promoting digital skills and innovation. He also serves as Project Manager and Frontend Engineer for RAYDAR, a child-safety initiative leveraging technology to help protect children. With over 4,000 followers on LinkedIn, Steeve shares his tech journey, connects with emerging innovators, and inspires young people to use technology to create meaningful social impact."}, "track": {"fr": "Communication", "en": "Communication"}, "day": 1, "sessionIds": ["agenda-networking-and-visibility"], "social": {"linkedin": "https://www.linkedin.com/in/steeve-zali-5a70b6379", "website": "https://tekmenrevolution.com/"}, "icebreakerQuestion": {"fr": "Is it really about what you know, or who you know?", "en": "Is it really about what you know, or who you know?"}, "icebreakerAnswer": {"fr": "Skills get you ready. Networking opens doors. Visibility gets you noticed.", "en": "Skills get you ready. Networking opens doors. Visibility gets you noticed."}}, {"id": "hypolit-zeuchieu", "name": "Hypolit Zeuchieu", "role": {"fr": "Trust Consulting, Backend Developer", "en": "Trust Consulting, Backend Developer"}, "company": "", "photoUrl": "/speakers/hypolit-zeuchieu.webp", "bio": {"fr": "I'm a self-taught Python developer based in Yaoundé, Cameroon. With a background in mathematics, I came to programming through curiosity, wanting to understand the simulation tools I used during my undergraduate studies at the University of Dschang. Over the past two years, I have built web projects, automation scripts, and personal tools documented on GitHub. I'm currently working in the tech industry and am passionate about making Python more accessible to developers worldwide.", "en": "I'm a self-taught Python developer based in Yaoundé, Cameroon. With a background in mathematics, I came to programming through curiosity, wanting to understand the simulation tools I used during my undergraduate studies at the University of Dschang. Over the past two years, I have built web projects, automation scripts, and personal tools documented on GitHub. I'm currently working in the tech industry and am passionate about making Python more accessible to developers worldwide."}, "track": {"fr": "Web", "en": "Web"}, "day": 1, "sessionIds": ["agenda-is-your-sign-in-with-button-really-safe"], "social": {"linkedin": "https://www.linkedin.com/in/hypolit-zeuchieu-a159392b7", "x": "https://x.com/HZeuchieu", "website": "https://trustconsulting.tech/"}, "icebreakerQuestion": {"fr": "", "en": ""}, "icebreakerAnswer": {"fr": "", "en": ""}}]$sp$::jsonb) with ordinality as t(x, o)
  where not exists (
    select 1 from jsonb_array_elements(d.payload) e where e ->> 'id' = x ->> 'id'
  )
), '[]'::jsonb)
where d.id = 'speakers';

update public.editorial_documents d
set payload = (
  select jsonb_agg(
    case
      when p.patch is not null and jsonb_array_length(coalesce(e -> 'speakerIds', '[]'::jsonb)) = 0
      then e || p.patch
      else e
    end
    order by o)
  from jsonb_array_elements(d.payload) with ordinality as t(e, o)
  left join lateral (
    select value as patch
    from jsonb_each($pt${"agenda-au-dela-de-la-technologie-construire-des-startup": {"speakerIds": ["forlan-noumechi"], "description": {"fr": "Une bonne technologie ne suffit pas à construire une grande startup. Le produit doit aussi être compris, bien présenté et inspirer confiance._x000D_\n_x000D_\nCette session explore le rôle du design, de l’identité visuelle, de l’expérience utilisateur et de la communication dans la construction de startups africaines crédibles et mémorables.", "en": "Une bonne technologie ne suffit pas à construire une grande startup. Le produit doit aussi être compris, bien présenté et inspirer confiance._x000D_\n_x000D_\nCette session explore le rôle du design, de l’identité visuelle, de l’expérience utilisateur et de la communication dans la construction de startups africaines crédibles et mémorables."}, "language": ["fr"], "originalLanguage": "fr", "track": {"fr": "UX/UI Design", "en": "UX/UI Design"}, "tags": [{"fr": "UX/UI Design", "en": "UX/UI Design"}, {"fr": "Business", "en": "Business"}], "level": "intermediate"}, "agenda-genui-making-mobile-interfaces-dynamic-with-ai": {"speakerIds": ["yunwen-eric"], "description": {"fr": "What if mobile interfaces could adapt to users' needs instead of relying on developers to hardcode every screen? Generative UI (GenUI) is changing how we think about mobile app development by enabling AI to generate dynamic, context-aware user interfaces in response to user requests and real-time context._x000D_\n_x000D_\nIn this session, we will explore the concept of GenUI, how it works, and how AI can move mobile experiences beyond static layouts toward more adaptive and personalized interactions. Through practical examples and demonstrations, attendees will discover the possibilities, challenges, and design considerations of integrating generative UI into mobile applications._x000D_\n_x000D_\nWhether you are a mobile developer, UI/UX designer, or AI enthusiast, this talk will help you understand how GenUI could shape the next generation of mobile experiences.", "en": "What if mobile interfaces could adapt to users' needs instead of relying on developers to hardcode every screen? Generative UI (GenUI) is changing how we think about mobile app development by enabling AI to generate dynamic, context-aware user interfaces in response to user requests and real-time context._x000D_\n_x000D_\nIn this session, we will explore the concept of GenUI, how it works, and how AI can move mobile experiences beyond static layouts toward more adaptive and personalized interactions. Through practical examples and demonstrations, attendees will discover the possibilities, challenges, and design considerations of integrating generative UI into mobile applications._x000D_\n_x000D_\nWhether you are a mobile developer, UI/UX designer, or AI enthusiast, this talk will help you understand how GenUI could shape the next generation of mobile experiences."}, "language": ["en"], "originalLanguage": "en", "track": {"fr": "Mobile", "en": "Mobile"}, "tags": [{"fr": "Mobile", "en": "Mobile"}, {"fr": "AI", "en": "AI"}], "level": "introductory"}, "agenda-networking-and-visibility": {"speakerIds": ["steeve-zali"], "description": {"fr": "This session will help students and young tech professionals understand what networking really means, why it matters, and how intentional relationships can accelerate their personal and professional growth. Participants will also explore the importance of visibility, from building a strong professional presence online to showcasing projects, sharing knowledge, and contributing to the tech community._x000D_\n_x000D_\nIn today's tech ecosystem, technical skills alone are not always enough to unlock opportunities. Knowing how to build meaningful relationships, communicate your value, and make your work visible can open doors to internships, collaborations, mentorship, jobs, and entrepreneurial opportunities._x000D_\n_x000D_\nThrough practical exercises, interactive discussions, and real-life scenarios, attendees will learn how to introduce themselves confidently, initiate meaningful conversations, follow up with new connections, and turn their skills and projects into visible opportunities._x000D_\n_x000D_\nBy the end of the session, participants will leave with actionable strategies to build their network, strengthen their personal brand, and become more intentional about creating opportunities rather than simply waiting for them.", "en": "This session will help students and young tech professionals understand what networking really means, why it matters, and how intentional relationships can accelerate their personal and professional growth. Participants will also explore the importance of visibility, from building a strong professional presence online to showcasing projects, sharing knowledge, and contributing to the tech community._x000D_\n_x000D_\nIn today's tech ecosystem, technical skills alone are not always enough to unlock opportunities. Knowing how to build meaningful relationships, communicate your value, and make your work visible can open doors to internships, collaborations, mentorship, jobs, and entrepreneurial opportunities._x000D_\n_x000D_\nThrough practical exercises, interactive discussions, and real-life scenarios, attendees will learn how to introduce themselves confidently, initiate meaningful conversations, follow up with new connections, and turn their skills and projects into visible opportunities._x000D_\n_x000D_\nBy the end of the session, participants will leave with actionable strategies to build their network, strengthen their personal brand, and become more intentional about creating opportunities rather than simply waiting for them."}, "language": ["en", "fr"], "originalLanguage": "en", "track": {"fr": "Communication", "en": "Communication"}, "tags": [{"fr": "Communication", "en": "Communication"}], "level": "advanced"}, "agenda-is-your-sign-in-with-button-really-safe": {"speakerIds": ["hypolit-zeuchieu"], "description": {"fr": "Signing in or linking an account with Google, GitHub, or Facebook has become second nature for both users and developers. Yet behind that single button lies a complex logic (OAuth 2.0, OpenID Connect, account merging, email handling) that many applications implement poorly._x000D_\n_x000D_\nIn this talk, we will show, through live demos on a deliberately vulnerable application, how a flawed implementation of social account linking can lead to account takeover and data leaks. We will walk through the most common mistakes: missing validation of the state parameter (OAuth CSRF), automatic account linking based on unverified emails, weak redirect_uri handling, exposed or poorly stored tokens, and “pre-account takeover” scenarios._x000D_\n_x000D_\nFor each vulnerability, we will explain the attacker’s reasoning, then show how to fix it in code. You will leave with a practical checklist to audit and secure social authentication in your own applications._x000D_\n_x000D_\nWhat attendees will learn:_x000D_\n_x000D_\n-How the OAuth 2.0 / OpenID Connect flow works, and where it can break_x000D_\n-How to recognize the most common implementation mistakes_x000D_\n-How these flaws are exploited, demonstrated in a controlled environment_x000D_\n-Best practices and a checklist to secure account linking", "en": "Signing in or linking an account with Google, GitHub, or Facebook has become second nature for both users and developers. Yet behind that single button lies a complex logic (OAuth 2.0, OpenID Connect, account merging, email handling) that many applications implement poorly._x000D_\n_x000D_\nIn this talk, we will show, through live demos on a deliberately vulnerable application, how a flawed implementation of social account linking can lead to account takeover and data leaks. We will walk through the most common mistakes: missing validation of the state parameter (OAuth CSRF), automatic account linking based on unverified emails, weak redirect_uri handling, exposed or poorly stored tokens, and “pre-account takeover” scenarios._x000D_\n_x000D_\nFor each vulnerability, we will explain the attacker’s reasoning, then show how to fix it in code. You will leave with a practical checklist to audit and secure social authentication in your own applications._x000D_\n_x000D_\nWhat attendees will learn:_x000D_\n_x000D_\n-How the OAuth 2.0 / OpenID Connect flow works, and where it can break_x000D_\n-How to recognize the most common implementation mistakes_x000D_\n-How these flaws are exploited, demonstrated in a controlled environment_x000D_\n-Best practices and a checklist to secure account linking"}, "language": ["en"], "originalLanguage": "en", "track": {"fr": "Web", "en": "Web"}, "tags": [{"fr": "Web", "en": "Web"}, {"fr": "Cybersecurity", "en": "Cybersecurity"}], "level": "intermediate"}}$pt$::jsonb)
    where key = e ->> 'id'
    limit 1
  ) p on true
)
where d.id = 'sessions';
